Maintain a deque containing indices of negative values in the current window. Remove indices that have moved outside. The front then identifies the first negative number.

from collections import deque

def first_negative(nums, k):
    if k <= 0 or k > len(nums):
        return []

    negatives = deque()
    answer = []

    for right, value in enumerate(nums):
        if value < 0:
            negatives.append(right)

        left = right - k + 1
        if left >= 0:
            while negatives and negatives[0] < left:
                negatives.popleft()
            answer.append(nums[negatives[0]] if negatives else 0)

    return answer

print(first_negative([12, -1, -7, 8, -15, 30, 16, 28], 3))

This is a variable-size window. Remember the latest index of every character. When a duplicate lies inside the current window, move left to one position after that duplicate.

def longest_unique_substring(s):
    last_seen = {}
    left = 0
    best = 0

    for right, ch in enumerate(s):
        if ch in last_seen and last_seen[ch] >= left:
            left = last_seen[ch] + 1
        last_seen[ch] = right
        best = max(best, right - left + 1)

    return best

print(longest_unique_substring('abcabcbb'))  # 3
